/**
 * @suppress
 */
public object FfiConverterTypeRSession: FfiConverter<RSession, Long> {
    override fun lower(value: RSession): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): RSession {
        return RSession(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RSession {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RSession) = 8UL

    override fun write(value: RSession, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * RGBA bitmap image returned from plot functions.
 */
data class PlotImage (
    var `width`: kotlin.UInt
    , 
    var `height`: kotlin.UInt
    , 
    var `rgbaBytes`: kotlin.ByteArray
    
){
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePlotImage: FfiConverterRustBuffer<PlotImage> {
    override fun read(buf: ByteBuffer): PlotImage {
        return PlotImage(
            FfiConverterUInt.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterByteArray.read(buf),
        )
    }

    override fun allocationSize(value: PlotImage) = (
            FfiConverterUInt.allocationSize(value.`width`) +
            FfiConverterUInt.allocationSize(value.`height`) +
            FfiConverterByteArray.allocationSize(value.`rgbaBytes`)
    )

    override fun write(value: PlotImage, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`width`, buf)
            FfiConverterUInt.write(value.`height`, buf)
            FfiConverterByteArray.write(value.`rgbaBytes`, buf)
    }
}



/**
 * Result of an R evaluation.
 */
data class RResult (
    var `value`: kotlin.Double
    , 
    var `output`: kotlin.String
    
){
    

    
