/**
 * Supported Bessel function families.
 */

enum class RBesselFunc {
    
    J,
    Y,
    I,
    K;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeRBesselFunc: FfiConverterRustBuffer<RBesselFunc> {
    override fun read(buf: ByteBuffer) = try {
        RBesselFunc.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: RBesselFunc) = 4UL

    override fun write(value: RBesselFunc, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





